{"operationName":"Schedule","query":"query Schedule($first: Int, $cursor: String, $filter: eventFilter) {
      schedule(first: $first, after: $cursor, filter: $filter) { edges { node { 
  eventId name type description from to status arrivalTime
  locationDetails locationAddress locationLink
  ageGroup { id name }
  groups { id name }
  currentPlayerAttendance { status coachStatus player { id displayName } }
 } } pageInfo { hasNextPage endCursor } }
    }","variables":{"first":20,"cursor":"n1"}}

{"operationName":"Event","query":"query Event($id: String!, $ageGroupId: String!) {
        event(id: $id, ageGroupId: $ageGroupId, first: 1) { edges { node { 
  eventId name type description from to status arrivalTime
  locationDetails locationAddress locationLink
  ageGroup { id name }
  groups { id name }
  currentPlayerAttendance { status coachStatus player { id displayName } }
 } } pageInfo { hasNextPage endCursor } }
      }","variables":{"id":"e1","ageGroupId":"g1"}}

{"operationName":"Conversations","query":"query Conversations($first: Int, $cursor: String) {
        getMessageUnreadCount
        message(first: $first, after: $cursor) {
          edges { node {
            id name conversationType membersCount unreadCount
            messageGroup { id name }
            user1 { id displayName }
            user2 { id displayName }
            messages(first: 1) { edges { node { 
  id messageBody createdAt
  creator { id displayName }
  attachments { id fileName description contentType }
  recipient { isRead }
 } } }
          } }
          pageInfo { hasNextPage endCursor }
        }
      }","variables":{"first":20,"cursor":null}}
